import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
c = 0
for idx in range(n - 1):
    if (isp(a[idx])) and (isp(a[idx + 1])):
        c += 1
print(c)

